+
+/// Parses composite `namespace/project#123`, `gl-123`, or bare IID [k].
+GlKeyParts parseGlIssueKey(String? k) {
+  if (k == null) return (projectPath: null, iid: null);
+  final sep = k.lastIndexOf('#');
+  if (sep > 0 &&
+      sep < k.length - 1 &&
+      _glBareDigits.hasMatch(k.substring(sep + 1))) {
