+  /// `gitlab_reopen_issue` — PUT `projects/{id}/issues/{iid}` `state_event=reopen`.
+  Future<Map<String, dynamic>?> reopenIssueByRef(GlIssueRef ref) =>
+      _putObject(_issuePath(ref), jsonEncode(const {'state_event': 'reopen'}));
