  void addLabel(String key, String label) => _run(
        key,
        'github_add_labels',
        (owner, repo, number) => {
          'owner': owner,
          'repo': repo,
          'number': number,
          'labels': [label],
        },
      );

  /// Removes [label] from the issue (Java `deleteLabelInTicket`).
  void removeLabel(String key, String label) => _run(
        key,
        'github_remove_label',
        (owner, repo, number) => {
          'owner': owner,
          'repo': repo,
          'number': number,
          'label': label,
        },
